def write_batch(batch, expected_ids):
    assert set(batch.keys()) == set(expected_ids), (set(batch.keys()) ^ set(expected_ids))
    OUT.mkdir(parents=True, exist_ok=True)
    n = 0
    for cid in expected_ids:
        rec = batch[cid]
        doc = {"case_id": cid, "prediction_text": rec["prediction_text"],
               "basis": rec["basis"], "confidence": rec["confidence"], "trigger": rec["trigger"]}
        (OUT / f"{cid}.json").write_text(json.dumps(doc, ensure_ascii=False, indent=1), encoding="utf-8")
        n += 1
    assert n == len(expected_ids)
    return n

